mapper.sql:
WHERE s.deleted_flag = FALSE

    AND s.item_code ILIKE CONCAT('%', #{criteria.itemCode}, '%')


    AND s.item_name ILIKE CONCAT('%', #{criteria.itemName}, '%')


    AND s.variant ILIKE CONCAT('%', #{criteria.variant}, '%')


    AND s.hierarchy = #{criteria.hierarchy}


    AND s.category_l1 = #{criteria.categoryL1}


    AND s.category_l2 = #{criteria.categoryL2}

mapper.select:
SELECT id, item_code, supplier_code, supplier_type, supplier_contract, consignee_company,
       consignee_store, current_inventory_qty, created_at, updated_at
FROM consignment_external_supplier
WHERE item_code = #{itemCode}
  AND id = #{id}

mapper.delete:
DELETE FROM consignment_external_supplier
WHERE item_code = #{itemCode}
  AND id = #{id}

mapper.insert:
